          const updatedScale=M.scale(draft);dialog.querySelectorAll('[data-edge-estimate]').forEach(el=>{const i=Number(el.dataset.edgeEstimate),start=draft.points[i],end=draft.points[(i+1)%draft.points.length];el.textContent=t('Mesure estimée à l’échelle')+' : '+fmt(updatedScale?M.distance(start.xy,end.xy)*updatedScale/unit:null);});dialog.querySelectorAll('[data-adjust-edge]').forEach(button=>button.disabled=!updatedScale);
